def solve(nums):
    """Return length of longest strictly increasing subsequence in list nums.
    Uses O(n log n) patience sorting algorithm.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc seq of length i+1
    for x in nums:
        # find insertion point (first >= x) because we need strictly increasing
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

