def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    seen = [[False] * len(row) for row in grid]
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and not seen[r][c]:
                count += 1
                stack = [(r, c)]
                seen[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if (0 <= nr < rows and 0 <= nc < len(grid[nr])
                                and grid[nr][nc] == 1 and not seen[nr][nc]):
                            seen[nr][nc] = True
                            stack.append((nr, nc))
    return count

